// entities/models/tenant.go lines 109-120
func (m *Tenant) validateActivityStatus(formats strfmt.Registry) error {
	if swag.IsZero(m.ActivityStatus) { // not required
		return nil  // BUG: treats empty string/null as 'zero', skips validation!
	}

	// value enum
	if err := m.validateActivityStatusEnum("activityStatus", "body", m.ActivityStatus); err != nil {
		return err
	}

	return nil
}

// entities/schema/multi_tenancy.go lines 49-54 (intended default behavior)
func ActivityStatus(status string) string {
	if status == "" {
		return models.TenantActivityStatusHOT  // Should default AFTER validation rejects empty
	}
	return status
}
